-- 客户搜索的三字索引（2026-11-14，8.6 万客户提速：号码搜索、名字搜索、公海搜索原来每次整表 GLOB '*词*'）。说明见 src/lib/search-keyword.ts 的「三字索引」。
-- 两张 FTS5 trigram 表（区分大小写），各列原样存一份 + 号键（同 号键SQL，tests/search-trigram.test.ts 钉着）：
--   CustomerSearch：客户的 名字 / 学校 / 专业 / 年级 / 备注 / 电话，号键 = 号键SQL("phone")
--   CustomerExtraSearch：扩展资料的 WhatsApp / 邮箱 / 微信 / 国家 / 官网 / 旺旺，号键 = 号键SQL("whatsapp")
-- rowid 跟源表的 rowid，cid 存源表的客户 id；查询只认 cid（c.id IN (SELECT cid … MATCH ?)），rowid 只给触发器定位。
-- 只是索引：源表照旧是唯一的数据，这两张表随时可以按源表重建。所以这一份是 README 第 3 条之外的第三个例外（tests/migration-allowed-drops.ts 许可搜索索引）：
--   INSERT / DELETE 只许写这两张表，不碰任何业务表。每次启动整个重跑：
--   1) 建表、建触发器（IF NOT EXISTS）；触发器先建，回填期间线上照常写进来的行由触发器带上
--   2) 对不上的删掉（rowid 处的源行不在了、或换了客户 id：比如整库重建后 rowid 重排了）
--   3) 缺的按 rowid 分段补（每段 2 万行一句、各自提交：线上那份在跑时，一句占写锁的时间不超过 busy_timeout）；补过的段第二遍只查不写
-- 8.6 万客户库：第一次约 1.6 s（本机），之后每次启动约 0.1 s。

-- CustomerSearch（源表 Customer）
CREATE VIRTUAL TABLE IF NOT EXISTS "CustomerSearch" USING fts5(cid UNINDEXED, "name", "school", "major", "grade", "remark", "phone", "phoneKey", tokenize = 'trigram case_sensitive 1');
CREATE TRIGGER IF NOT EXISTS "CustomerSearch_ai" AFTER INSERT ON "Customer" BEGIN DELETE FROM "CustomerSearch" WHERE rowid = new.rowid; INSERT INTO "CustomerSearch"(rowid, cid, "name", "school", "major", "grade", "remark", "phone", "phoneKey") VALUES (new.rowid, new."id", new."name", new."school", new."major", new."grade", new."remark", new."phone", replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(new."phone", '０', '0'), '１', '1'), '２', '2'), '３', '3'), '４', '4'), '５', '5'), '６', '6'), '７', '7'), '８', '8'), '９', '9'), ' ', ''), '　', ''), '-', ''), '－', ''), '—', ''), '(', ''), ')', ''), '（', ''), '）', ''), '+', '')); END;
CREATE TRIGGER IF NOT EXISTS "CustomerSearch_ad" AFTER DELETE ON "Customer" BEGIN DELETE FROM "CustomerSearch" WHERE rowid = old.rowid; END;
CREATE TRIGGER IF NOT EXISTS "CustomerSearch_au" AFTER UPDATE OF "id", "name", "school", "major", "grade", "remark", "phone" ON "Customer" BEGIN DELETE FROM "CustomerSearch" WHERE rowid = old.rowid; DELETE FROM "CustomerSearch" WHERE rowid = new.rowid; INSERT INTO "CustomerSearch"(rowid, cid, "name", "school", "major", "grade", "remark", "phone", "phoneKey") VALUES (new.rowid, new."id", new."name", new."school", new."major", new."grade", new."remark", new."phone", replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(new."phone", '０', '0'), '１', '1'), '２', '2'), '３', '3'), '４', '4'), '５', '5'), '６', '6'), '７', '7'), '８', '8'), '９', '9'), ' ', ''), '　', ''), '-', ''), '－', ''), '—', ''), '(', ''), ')', ''), '（', ''), '）', ''), '+', '')); END;
DELETE FROM "CustomerSearch" WHERE rowid IN (SELECT f.rowid FROM "CustomerSearch" f LEFT JOIN "Customer" x ON x.rowid = f.rowid WHERE x."id" IS NOT f.cid);
INSERT INTO "CustomerSearch"(rowid, cid, "name", "school", "major", "grade", "remark", "phone", "phoneKey") SELECT x.rowid, x."id", x."name", x."school", x."major", x."grade", x."remark", x."phone", replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(x."phone", '０', '0'), '１', '1'), '２', '2'), '３', '3'), '４', '4'), '５', '5'), '６', '6'), '７', '7'), '８', '8'), '９', '9'), ' ', ''), '　', ''), '-', ''), '－', ''), '—', ''), '(', ''), ')', ''), '（', ''), '）', ''), '+', '') FROM "Customer" x WHERE x.rowid > 0 AND x.rowid <= 20000 AND x.rowid NOT IN (SELECT rowid FROM "CustomerSearch" WHERE rowid > 0 AND rowid <= 20000);
